"""Compare the write requests to data.mdb between runs, per 1,000-block window, from analyze_writes outputs
(writes.txt: one line per window "win blocks bios/blk MB/blk KB/bio node-own%").
Prints each run's write requests per block and MB per block, and each run against the first as a % change.
usage: writes_compare.py <baseline writes.txt> <writes.txt>...     e.g. no cache drop first, then the candidates"""
import re, sys

def load(p):
    w = {}
    for l in open(p):
        m = re.match(r"\s+(-?\d+)\s+(\d+)\s+([0-9.]+)\s+([0-9.]+)\s+([0-9.]+)\s+([0-9.]+)%", l)
        if m and int(m.group(1)) >= 0:
            w[int(m.group(1))] = (float(m.group(3)), float(m.group(4)))
    return w

runs = [(p, load(p)) for p in sys.argv[1:]]
base = runs[0][1]
for p, w in runs:
    print(p)
    for k in sorted(w):
        b = base.get(k)
        print("  window %d: %6.1f write requests/block, %.2f MB/block%s" % (k, w[k][0], w[k][1],
              "" if w is base else "; requests %+.0f%%, bytes %+.0f%% against the first" % (100 * (w[k][0] / b[0] - 1), 100 * (w[k][1] / b[1] - 1))))
